const raw = $input.first().json;
const body = (raw && typeof raw.body === 'object' && raw.body !== null) ? raw.body : raw;
const event = String(body.event || '');
const channels = body.channelsConfig || {};

const b64 = obj => Buffer.from(JSON.stringify(obj), 'utf8').toString('base64');

// 1. Boas-vindas (Welcome)
if (event === 'discord.member_join') {
  const guildId = String(body.guildId || '');
  const user = body.user || {};
  const payload = { guildId, userId: String(user.id || ''), username: String(user.globalName || user.username || 'novo membro') };
  const sql = `
    WITH p AS (SELECT convert_from(decode($1, 'base64'), 'UTF8')::jsonb AS j),
    up AS (
      INSERT INTO discord_server_stats (guild_id, members_joined, updated_at)
      SELECT p.j->>'guildId', 1, NOW() FROM p
      ON CONFLICT (guild_id) DO UPDATE SET
        members_joined = discord_server_stats.members_joined + 1,
        updated_at = NOW()
      RETURNING members_joined
    )
    SELECT jsonb_build_object('action', 'member_join', 'members_joined', (SELECT members_joined FROM up)) AS result;
  `;
  return [{ json: { mode: 'event', event, body, channels, sql, payloadB64: b64(payload) } }];
}

// 2. Atividade de mensagem (stats + AFK check)
if (event === 'discord.message_activity') {
  const guildId = String(body.guildId || '');
  const author = body.author || {};
  const mentionedUserIds = Array.isArray(body.mentionedUserIds) ? body.mentionedUserIds.map(String) : [];
  const payload = {
    guildId,
    authorId: String(author.id || ''),
    authorName: String(author.username || 'usuário'),
    mentionedUserIds
  };
  const sql = `
    WITH p AS (SELECT convert_from(decode($1, 'base64'), 'UTF8')::jsonb AS j),
    st AS (
      INSERT INTO discord_server_stats (guild_id, messages_count, updated_at)
      SELECT p.j->>'guildId', 1, NOW() FROM p
      ON CONFLICT (guild_id) DO UPDATE SET
        messages_count = discord_server_stats.messages_count + 1,
        updated_at = NOW()
    ),
    cleared AS (
      DELETE FROM discord_afk
      WHERE user_id = (SELECT p.j->>'authorId' FROM p)
      RETURNING user_id, username, reason, since_at
    ),
    mentioned AS (
      SELECT user_id, username, reason, since_at
      FROM discord_afk
      WHERE user_id = ANY(
        SELECT jsonb_array_elements_text((SELECT COALESCE(p.j->'mentionedUserIds', '[]'::jsonb) FROM p))
      )
    )
    SELECT jsonb_build_object(
      'action', 'message_activity',
      'clearedAfk', (SELECT row_to_json(cleared) FROM cleared LIMIT 1),
      'mentionedAfk', COALESCE((SELECT jsonb_agg(row_to_json(mentioned)) FROM mentioned), '[]'::jsonb)
    ) AS result;
  `;
  return [{ json: { mode: 'event', event, body, channels, sql, payloadB64: b64(payload) } }];
}

// 3. Slash commands de comunidade
if (event === 'discord.slash_command') {
  const cmd = String(body.commandName || '');
  const opts = body.options || {};
  const user = body.user || {};
  const guildId = String(body.guildId || 'dm');
  const channelId = String(body.channelId || '');
  const userId = String(user.id || '');
  const username = String(user.globalName || user.username || 'usuário');

  if (cmd === 'afk') {
    const reason = String(opts.motivo || 'Ausente no momento').slice(0, 200);
    const payload = { userId, guildId, username, reason };
    const sql = `
      WITH p AS (SELECT convert_from(decode($1, 'base64'), 'UTF8')::jsonb AS j),
      st AS (
        INSERT INTO discord_server_stats (guild_id, commands_count, updated_at)
        SELECT p.j->>'guildId', 1, NOW() FROM p
        ON CONFLICT (guild_id) DO UPDATE SET commands_count = discord_server_stats.commands_count + 1, updated_at = NOW()
      ),
      up AS (
        INSERT INTO discord_afk (user_id, guild_id, username, reason, since_at)
        SELECT p.j->>'userId', p.j->>'guildId', p.j->>'username', p.j->>'reason', NOW() FROM p
        ON CONFLICT (user_id) DO UPDATE SET reason = EXCLUDED.reason, username = EXCLUDED.username, since_at = NOW()
        RETURNING reason
      )
      SELECT jsonb_build_object('action', 'afk', 'reason', (SELECT reason FROM up)) AS result;
    `;
    return [{ json: { mode: 'slash', commandName: cmd, body, channels, sql, payloadB64: b64(payload) } }];
  }

  if (cmd === 'aniversario') {
    const acao = String(opts.acao || 'listar');
    const dia = Number(opts.dia || 0);
    const mes = Number(opts.mes || 0);
    const payload = { acao, userId, guildId, username, dia, mes };
    const sql = acao === 'registrar'
      ? `
        WITH p AS (SELECT convert_from(decode($1, 'base64'), 'UTF8')::jsonb AS j),
        up AS (
          INSERT INTO discord_birthdays (user_id, guild_id, username, birth_day, birth_month)
          SELECT p.j->>'userId', p.j->>'guildId', p.j->>'username', (p.j->>'dia')::int, (p.j->>'mes')::int FROM p
          WHERE (p.j->>'dia')::int BETWEEN 1 AND 31 AND (p.j->>'mes')::int BETWEEN 1 AND 12
          ON CONFLICT (user_id) DO UPDATE SET username = EXCLUDED.username, birth_day = EXCLUDED.birth_day, birth_month = EXCLUDED.birth_month
          RETURNING birth_day, birth_month
        )
        SELECT jsonb_build_object('action', 'aniversario_registrar', 'saved', (SELECT row_to_json(up) FROM up LIMIT 1)) AS result;
      `
      : `
        WITH p AS (SELECT convert_from(decode($1, 'base64'), 'UTF8')::jsonb AS j),
        rows AS (
          SELECT username, birth_day, birth_month FROM discord_birthdays
          WHERE guild_id = (SELECT p.j->>'guildId' FROM p)
          ORDER BY birth_month, birth_day LIMIT 15
        )
        SELECT jsonb_build_object('action', 'aniversario_listar', 'list', COALESCE((SELECT jsonb_agg(row_to_json(rows)) FROM rows), '[]'::jsonb)) AS result;
      `;
    return [{ json: { mode: 'slash', commandName: cmd, body, channels, sql, payloadB64: b64(payload) } }];
  }

  if (cmd === 'nota') {
    const acao = String(opts.acao || 'listar');
    const titulo = String(opts.titulo || '').trim().slice(0, 100);
    const conteudo = String(opts.conteudo || '').trim().slice(0, 1000);
    const payload = { acao, userId, titulo, conteudo };
    let sql = '';
    if (acao === 'salvar') {
      sql = `
        WITH p AS (SELECT convert_from(decode($1, 'base64'), 'UTF8')::jsonb AS j),
        ins AS (
          INSERT INTO discord_notes (user_id, title, content)
          SELECT p.j->>'userId', COALESCE(NULLIF(p.j->>'titulo', ''), 'Nota rápida'), p.j->>'conteudo' FROM p
          WHERE COALESCE(p.j->>'conteudo', '') <> ''
          RETURNING id, title
        )
        SELECT jsonb_build_object('action', 'nota_salvar', 'saved', (SELECT row_to_json(ins) FROM ins LIMIT 1)) AS result;
      `;
    } else if (acao === 'apagar') {
      sql = `
        WITH p AS (SELECT convert_from(decode($1, 'base64'), 'UTF8')::jsonb AS j),
        del AS (
          DELETE FROM discord_notes
          WHERE user_id = (SELECT p.j->>'userId' FROM p)
            AND (id::text = (SELECT p.j->>'titulo' FROM p) OR LOWER(title) = LOWER((SELECT p.j->>'titulo' FROM p)))
          RETURNING id, title
        )
        SELECT jsonb_build_object('action', 'nota_apagar', 'deletedCount', (SELECT COUNT(*) FROM del)) AS result;
      `;
    } else {
      sql = `
        WITH p AS (SELECT convert_from(decode($1, 'base64'), 'UTF8')::jsonb AS j),
        rows AS (
          SELECT id, title, content, created_at FROM discord_notes
          WHERE user_id = (SELECT p.j->>'userId' FROM p)
          ORDER BY created_at DESC LIMIT 10
        )
        SELECT jsonb_build_object('action', 'nota_listar', 'notes', COALESCE((SELECT jsonb_agg(row_to_json(rows)) FROM rows), '[]'::jsonb)) AS result;
      `;
    }
    return [{ json: { mode: 'slash', commandName: cmd, body, channels, sql, payloadB64: b64(payload) } }];
  }

  if (cmd === 'sugestao') {
    const texto = String(opts.texto || '').trim().slice(0, 1000);
    const payload = { guildId, userId, username, texto };
    const sql = `
      WITH p AS (SELECT convert_from(decode($1, 'base64'), 'UTF8')::jsonb AS j),
      ins AS (
        INSERT INTO discord_suggestions (guild_id, user_id, username, content)
        SELECT p.j->>'guildId', p.j->>'userId', p.j->>'username', p.j->>'texto' FROM p
        RETURNING id, content, username
      )
      SELECT jsonb_build_object('action', 'sugestao', 'suggestion', (SELECT row_to_json(ins) FROM ins LIMIT 1)) AS result;
    `;
    return [{ json: { mode: 'slash', commandName: cmd, body, channels, sql, payloadB64: b64(payload) } }];
  }

  if (cmd === 'sorteio') {
    const premio = String(opts.premio || 'Prêmio surpresa').trim().slice(0, 200);
    const duracao = Math.max(1, Math.min(10080, Number(opts.duracao_minutos || 10)));
    const vencedores = Math.max(1, Math.min(10, Number(opts.vencedores || 1)));
    const payload = { guildId, channelId, prize: premio, winnersCount: vencedores, durationMin: duracao, hostId: userId };
    const sql = `
      WITH p AS (SELECT convert_from(decode($1, 'base64'), 'UTF8')::jsonb AS j),
      ins AS (
        INSERT INTO discord_giveaways (guild_id, channel_id, prize, winners_count, ends_at, host_id)
        SELECT p.j->>'guildId', p.j->>'channelId', p.j->>'prize', (p.j->>'winnersCount')::int, NOW() + ((p.j->>'durationMin')::int * INTERVAL '1 minute'), p.j->>'hostId' FROM p
        RETURNING id, prize, winners_count, ends_at
      )
      SELECT jsonb_build_object('action', 'sorteio', 'giveaway', (SELECT row_to_json(ins) FROM ins LIMIT 1)) AS result;
    `;
    return [{ json: { mode: 'slash', commandName: cmd, body, channels, sql, payloadB64: b64(payload) } }];
  }

  if (cmd === 'stats') {
    const payload = { guildId };
    const sql = `
      WITH p AS (SELECT convert_from(decode($1, 'base64'), 'UTF8')::jsonb AS j)
      SELECT jsonb_build_object(
        'action', 'stats',
        'server', (SELECT row_to_json(s) FROM discord_server_stats s WHERE s.guild_id = (SELECT p.j->>'guildId' FROM p)),
        'afkCount', (SELECT COUNT(*) FROM discord_afk WHERE guild_id = (SELECT p.j->>'guildId' FROM p)),
        'suggestionsCount', (SELECT COUNT(*) FROM discord_suggestions WHERE guild_id = (SELECT p.j->>'guildId' FROM p)),
        'activeGiveaways', (SELECT COUNT(*) FROM discord_giveaways WHERE guild_id = (SELECT p.j->>'guildId' FROM p) AND ended = FALSE),
        'apiLastHour', (SELECT COUNT(*) FROM obs_api_logs WHERE created_at >= NOW() - INTERVAL '1 hour')
      ) AS result;
    `;
    return [{ json: { mode: 'slash', commandName: cmd, body, channels, sql, payloadB64: b64(payload) } }];
  }

  if (cmd === 'obs') {
    const payload = {};
    const sql = `
      SELECT jsonb_build_object(
        'action', 'obs',
        'apiTotal', (SELECT COUNT(*) FROM obs_api_logs WHERE created_at >= NOW() - INTERVAL '24 hours'),
        'apiErrors', (SELECT COUNT(*) FROM obs_api_logs WHERE created_at >= NOW() - INTERVAL '24 hours' AND (is_error OR status_code >= 400)),
        'apiAvgMs', (SELECT COALESCE(ROUND(AVG(duration_ms))::int, 0) FROM obs_api_logs WHERE created_at >= NOW() - INTERVAL '24 hours'),
        'errorsTotal', (SELECT COUNT(*) FROM obs_error_logs WHERE created_at >= NOW() - INTERVAL '24 hours'),
        'n8nTotal', (SELECT COUNT(*) FROM obs_n8n_executions WHERE created_at >= NOW() - INTERVAL '24 hours'),
        'n8nErrors', (SELECT COUNT(*) FROM obs_n8n_executions WHERE created_at >= NOW() - INTERVAL '24 hours' AND status = 'error')
      ) AS result;
    `;
    return [{ json: { mode: 'slash', commandName: cmd, body, channels, sql, payloadB64: b64(payload) } }];
  }
}

throw new Error(`Evento de comunidade não reconhecido: ${event}`);

const ctx = $('Roteador de Engajamento e SQL').item.json;
const res = ($input.first().json && $input.first().json.result) || {};
const body = ctx.body || {};
const channels = ctx.channels || {};
const calls = [];

const addJsonCall = (method, url, payload, meta = {}) => {
  calls.push({
    json: {
      method,
      url,
      hasBody: true,
      bodyJson: JSON.stringify(payload),
      meta
    }
  });
};

if (ctx.event === 'discord.member_join') {
  const welcomeCh = channels.welcomeChannelId;
  const user = body.user || {};
  if (welcomeCh) {
    addJsonCall('POST', `https://discord.com/api/v10/channels/${welcomeCh}/messages`, {
      content: `Bem-vindo(a) ao servidor, <@${user.id}>! 💜`,
      embeds: [{
        title: `✨ Novo membro em ${body.guildName || 'nossa comunidade'}!`,
        description: `Oi **${user.globalName || user.username}**! Eu sou a Usami. Fique à vontade para conversar comigo ou usar \`/nota\`, \`/sugestao\` e \`/afk\`!`,
        color: 16735870,
        thumbnail: user.avatarUrl ? { url: user.avatarUrl } : undefined,
        footer: { text: `Membro #${body.memberCount || res.members_joined || 1}` }
      }]
    });
  }
}

if (ctx.event === 'discord.message_activity') {
  const ch = body.channelId;
  if (res.clearedAfk && ch) {
    addJsonCall('POST', `https://discord.com/api/v10/channels/${ch}/messages`, {
      content: `Bem-vindo(a) de volta, <@${body.author.id}>! Removi seu status **AFK**.`
    });
  }
  const mentionedAfk = Array.isArray(res.mentionedAfk) ? res.mentionedAfk : [];
  if (mentionedAfk.length > 0 && ch) {
    const lines = mentionedAfk.map(a => `• **${a.username}** está AFK: _${a.reason}_`);
    addJsonCall('POST', `https://discord.com/api/v10/channels/${ch}/messages`, {
      content: lines.join('\n'),
      allowed_mentions: { parse: [] }
    });
  }
}

if (ctx.mode === 'slash') {
  const patchUrl = body.webhookPatchUrl;
  const cmd = ctx.commandName;
  if (cmd === 'afk') {
    addJsonCall('PATCH', patchUrl, {
      content: `🌙 Status **AFK** ativado! Motivo: _${res.reason || 'Ausente no momento'}_`
    });
  } else if (cmd === 'aniversario') {
    if (res.action === 'aniversario_registrar') {
      const msg = res.saved
        ? `🎂 Aniversário salvo para **${String(res.saved.birth_day).padStart(2, '0')}/${String(res.saved.birth_month).padStart(2, '0')}**!`
        : 'Informe um dia (1-31) e mês (1-12) válidos para registrar seu aniversário.';
      addJsonCall('PATCH', patchUrl, { content: msg });
    } else {
      const list = Array.isArray(res.list) ? res.list : [];
      const lines = list.length
        ? list.map(b => `• **${b.username}** — ${String(b.birth_day).padStart(2, '0')}/${String(b.birth_month).padStart(2, '0')}`).join('\n')
        : 'Nenhum aniversário cadastrado ainda. Use `/aniversario registrar`!';
      addJsonCall('PATCH', patchUrl, { embeds: [{ title: '🎂 Aniversários do Servidor', description: lines, color: 16754377 }] });
    }
  } else if (cmd === 'nota') {
    if (res.action === 'nota_salvar') {
      addJsonCall('PATCH', patchUrl, {
        content: res.saved ? `📝 Nota **#${res.saved.id} (${res.saved.title})** salva com sucesso!` : 'Informe o conteúdo da nota para salvar.'
      });
    } else if (res.action === 'nota_apagar') {
      addJsonCall('PATCH', patchUrl, {
        content: Number(res.deletedCount) > 0 ? `🗑️ ${res.deletedCount} nota(s) removida(s).` : 'Nenhuma nota encontrada com esse ID ou título.'
      });
    } else {
      const notes = Array.isArray(res.notes) ? res.notes : [];
      const desc = notes.length
        ? notes.map(n => `**#${n.id} — ${n.title}**\n${String(n.content).slice(0, 120)}`).join('\n\n')
        : 'Você ainda não tem notas salvas. Use `/nota salvar`!';
      addJsonCall('PATCH', patchUrl, { embeds: [{ title: '📒 Seu Notepad', description: desc, color: 2633026 }] });
    }
  } else if (cmd === 'sugestao') {
    const s = res.suggestion || {};
    const targetCh = channels.suggestionsChannelId || body.channelId;
    addJsonCall('PATCH', patchUrl, {
      content: `💡 Sugestão **#${s.id || ''}** publicada para votação em <#${targetCh}>!`
    });
    addJsonCall('POST', `https://discord.com/api/v10/channels/${targetCh}/messages`, {
      embeds: [{
        title: `💡 Sugestão #${s.id || ''}`,
        description: s.content || '',
        color: 16754377,
        footer: { text: `Enviada por ${s.username || 'membro'} • Reaja com 👍 ou 👎` }
      }]
    }, { reactEmojis: ['👍', '👎'], channelId: targetCh });
  } else if (cmd === 'sorteio') {
    const g = res.giveaway || {};
    const endsUnix = g.ends_at ? Math.floor(new Date(g.ends_at).getTime() / 1000) : Math.floor(Date.now() / 1000 + 600);
    addJsonCall('PATCH', patchUrl, {
      content: `🎉 Sorteio **#${g.id || ''}** iniciado!`,
      embeds: [{
        title: `🎁 Sorteio: ${g.prize || 'Prêmio'}`,
        description: `Reaja com 🎉 para participar!\nVencedores: **${g.winners_count || 1}**\nEncerra: <t:${endsUnix}:R>`,
        color: 16735870,
        footer: { text: `Sorteio #${g.id || ''}` }
      }]
    }, { giveawayId: g.id, channelId: body.channelId, reactEmojis: ['🎉'] });
  } else if (cmd === 'stats') {
    const srv = res.server || {};
    addJsonCall('PATCH', patchUrl, {
      embeds: [{
        title: '📈 Estatísticas da Comunidade & Usami',
        color: 16735870,
        fields: [
          { name: 'Mensagens contadas', value: String(srv.messages_count || 0), inline: true },
          { name: 'Comandos executados', value: String(srv.commands_count || 0), inline: true },
          { name: 'Membros acolhidos', value: String(srv.members_joined || 0), inline: true },
          { name: 'Usuários AFK', value: String(res.afkCount || 0), inline: true },
          { name: 'Sugestões registradas', value: String(res.suggestionsCount || 0), inline: true },
          { name: 'Chamadas API Usami (1h)', value: String(res.apiLastHour || 0), inline: true }
        ]
      }]
    });
  } else if (cmd === 'obs') {
    addJsonCall('PATCH', patchUrl, {
      embeds: [{
        title: '🩺 Observabilidade Usami (Últimas 24h)',
        color: (Number(res.errorsTotal || 0) > 0 || Number(res.n8nErrors || 0) > 0) ? 16753920 : 5763719,
        fields: [
          { name: 'Eventos API / LLM', value: `${res.apiTotal || 0} (${res.apiErrors || 0} falhas)`, inline: true },
          { name: 'Latência média API', value: `${res.apiAvgMs || 0} ms`, inline: true },
          { name: 'Execuções n8n', value: `${res.n8nTotal || 0} (${res.n8nErrors || 0} erros)`, inline: true },
          { name: 'Erros registrados', value: String(res.errorsTotal || 0), inline: true }
        ]
      }]
    });
  }
}

return calls;

const items = $input.all();
const calls = $('Montar Chamadas Discord').all();
const reactions = [];
let giveawayUpdate = null;

for (let i = 0; i < items.length; i++) {
  const res = items[i].json || {};
  const meta = (calls[i] && calls[i].json && calls[i].json.meta) || {};
  const msgId = res.id;
  const chId = res.channel_id || meta.channelId;
  if (msgId && chId && Array.isArray(meta.reactEmojis)) {
    for (const emoji of meta.reactEmojis) {
      reactions.push({
        json: {
          url: `https://discord.com/api/v10/channels/${chId}/messages/${msgId}/reactions/${encodeURIComponent(emoji)}/@me`
        }
      });
    }
  }
  if (msgId && meta.giveawayId) {
    giveawayUpdate = { id: meta.giveawayId, messageId: String(msgId) };
  }
}

return reactions.map(r => ({
  json: {
    ...r.json,
    giveawayB64: giveawayUpdate ? Buffer.from(JSON.stringify(giveawayUpdate), 'utf8').toString('base64') : null
  }
}));

const res = ($input.first().json && $input.first().json.result) || {};
const list = Array.isArray(res.birthdays) ? res.birthdays : [];
let welcomeCh = '';
try {
  welcomeCh = ($env && $env.DISCORD_WELCOME_CHANNEL_ID) ? String($env.DISCORD_WELCOME_CHANNEL_ID).trim() : '';
} catch {
  welcomeCh = '';
}
if (!list.length || !welcomeCh) return [];

return list.map(b => ({
  json: {
    channelId: welcomeCh,
    bodyJson: JSON.stringify({
      content: `🎂 Feliz aniversário, <@${b.user_id}>!! Desejo um dia incrível cheio de coisas boas! 💜🎉`
    })
  }
}));

const giveaways = $('Encerrar Sorteios Vencidos').all();
const reactionResponses = $input.all();
const out = [];

for (let i = 0; i < giveaways.length; i++) {
  const g = giveaways[i].json;
  const rawUsers = reactionResponses[i]?.json;
  const users = Array.isArray(rawUsers) ? rawUsers.filter(u => u && !u.bot && u.id) : [];
  const pool = [...users];
  const winners = [];
  const targetCount = Math.min(Number(g.winners_count || 1), pool.length);
  for (let w = 0; w < targetCount; w++) {
    const idx = Math.floor(Math.random() * pool.length);
    winners.push(pool.splice(idx, 1)[0]);
  }
  const content = winners.length
    ? `🎉 Sorteio **#${g.id} (${g.prize})** encerrado! Parabéns: ${winners.map(u => `<@${u.id}>`).join(', ')}! 🏆`
    : `🎉 Sorteio **#${g.id} (${g.prize})** encerrado, mas não houve participantes válidos.`;
  out.push({
    json: {
      channelId: g.channel_id,
      bodyJson: JSON.stringify({ content })
    }
  });
}
return out;
